async function moveResident(npcId: string, homeTileId: string): Promise<void> {
  if (!oncommand('MOVE_NPC_HOME', { npcId, homeTileId })) return;
  const nextDrafts = { ...moveDrafts };
  delete nextDrafts[npcId];
  moveDrafts = nextDrafts;
  await tick();
  focusManage();
}

